PG.EXTRA['/festivals/ekadashi/overview/']=[
 _C('all26','ALL 26 AT A GLANCE','The year of Ekādaśīs',fig_row('Twelve lamps for twelve months',[(lamp(),1)]*6,['']*6,gy=None),[('🌸','Caitra–Vaiśākha','Pāpamocanī, Kāmadā, Varūthinī, Mohinī.'),('☀️','Jyeṣṭha–Āṣāḍha','Aparā, Nirjalā, Yoginī, Devaśayanī.'),('🌧️','Śrāvaṇa–Bhādrapada','Kāmikā, Śrāvaṇa Putradā, Ajā, Parivartinī.'),('🍂','Āśvina–Kārtika','Indirā, Pāpāṅkuśā, Ramā, Prabodhinī.'),('❄️','Mārgaśīrṣa–Pauṣa','Utpannā, Mokṣadā, Saphalā, Pauṣa Putradā.'),('🌾','Māgha–Phālguna','Ṣaṭtilā, Jayā, Vijayā, Āmalakī.'),('🌙','Adhika Māsa','Padminī and Paramā, only in leap years.')],[('z','Twenty-six? I thought 24.'),('b','Twenty-four in a normal year. The leap month adds two more.')],'<b>24 a year</b>, 26 with the leap month.'),
 _R('texts','WHERE THE STORIES COME FROM','The sources of the māhātmyas',fig_row('A stack of old books',[(books_stack(),1.4),(book(),1.4)],['',''],gy=None),['<b>Padma Purāṇa.</b> Its Uttara Khaṇḍa holds most of the Ekādaśī māhātmyas, told by Kṛṣṇa to Yudhiṣṭhira.','<b>Bhaviṣyottara Purāṇa.</b> Another large collection, with many of the same stories in different words.','<b>Other Purāṇas.</b> Skanda, Brahmāṇḍa and Nārada Purāṇas add tellings; the Nārada Purāṇa has Rukmāṅgada’s story.','<b>Vrata books.</b> Later digests such as the Hari-bhakti-vilāsa (Gauḍīya) and regional Ekādaśī books gather the rules and stories. Editions differ in names and details.'],None,'Mostly <b>Padma and Bhaviṣyottara</b>.'),
 _C('keepers','FAMOUS KEEPERS OF THE VOW','Stories about Ekādaśī itself',fig_row('A king, a sage and the discus',[(person('#1d6fb8'),1.1),(sage('#ff8c1a'),1.1),(discus(),1.2)],['Ambarīṣa','Durvāsā','Sudarśana'],gy=160),[('👑','Ambarīṣa','The king of the Bhāgavata (Book 9) who kept Ekādaśī for a year; when he sipped water to break the fast while waiting for Durvāsā, the angry sage sent a demon, and Viṣṇu’s discus protected the king.'),('🧘','Durvāsā','Chased by the discus through the worlds until Viṣṇu sent him back to beg Ambarīṣa’s pardon.'),('👑','Rukmāṅgada','A king of the Nārada Purāṇa so devoted to Ekādaśī that he would break it for nothing, even when tested by Mohinī.'),('💪','Bhīma','Who kept just one, the waterless Nirjalā.')],[('z','Why did the king sip water?'),('b','To honour both rules: break the fast on time, yet not eat before his guest. Water counts as both eating and not eating.')],'<b>Ambarīṣa</b>: the model Ekādaśī keeper.')]
PG.EXTRA['/festivals/ekadashi/keeping-the-vow/']=[
 _C('foods','WHAT TO EAT AND AVOID','A practical list',fig_row('Fruit, milk and roots, with grains set aside',[(pot('#c0392b'),1),(pot('#fff'),1),(pot_rice(),1)],['fruit','milk','grains set aside'],gy=160),[('✅','Usually allowed','Fruits, milk, curd, nuts, sweet potato, potato, sāmā (barnyard millet) and sābudāna in many homes, rock salt.'),('❌','Usually avoided','Rice, wheat, all grains and pulses; in many homes also onion, garlic and some spices.'),('🏠','House custom','Lists differ by region and family; Mādhva and Gauḍīya traditions have their own.'),('🩺','Health first','Diabetics and anyone on regular medication should take medical advice before fasting.')],None,'<b>No grains</b>; the rest by custom.'),
 _R('mind','THE INNER FAST','What the outer fast is for',svg(560,140,'A seated figure in meditation with a lamp',g(240,130,1.2,sage('#1d6fb8'))+g(380,120,1.4,lamp())),['<b>Upavāsa.</b> The word means “dwelling near” (God), not just going without food.','<b>Speech.</b> No quarrels, harsh words or gossip; many keep silence for part of the day.','<b>Mind.</b> Nāma-japa, reading the Gītā or Viṣṇu Sahasranāma, hearing the day’s story.','<b>Senses.</b> Less screen, less noise, less sleep by day; more worship and service.'],None,'Fast the stomach, <b>feed the mind</b>.'),
 _R('day','A SIMPLE ORDER OF THE DAY','From dawn to dawn',svg(560,140,'Sun, lamp, book and moon in a row',g(110,80,1.2,sun())+g(230,100,1.3,lamp())+g(350,100,1.3,book())+g(470,80,1.2,moon())),['<b>Dawn.</b> Bath, a lamp before Viṣṇu, a saṅkalpa (intention) for the vow.','<b>Day.</b> Worship with tulasī, japa, reading; fast at your level.','<b>Evening.</b> Lamp, the day’s story, bhajana.','<b>Night and next dawn.</b> Vigil as you can; on Dvādaśī, worship, feed someone if you can, then break the fast within the pāraṇa window.'],None,'Dawn, day, dusk, <b>Dvādaśī</b>.')]

def L(i,t=None): return pages.link(i,t)
def moon_phases():
    o=''
    for k in range(15):
        x=30+k*34; f=k/14
        o+=f'<circle cx="{x}" cy="60" r="13" fill="#2a2a3a" stroke="#111" stroke-width="1.5"/><path d="M{x} 47 a13 13 0 0 1 0 26 a{13*(1-2*f) if f<.5 else 13*(2*f-1)} 13 0 0 {1 if f<.5 else 0} 0 -26z" fill="#fff8d0"/>'
        if k==10: o+=f'<circle cx="{x}" cy="60" r="18" fill="none" stroke="#c0392b" stroke-width="3"/>'+lab(x,100,'11th: Ekādaśī',11)
    return svg(560,120,'Fifteen moon phases of the bright fortnight with the eleventh circled',o)
# ---------------- Part 1
i=0
COV=covart('A crescent moon over a lamp and a tulasī plant, with Viṣṇu holding conch and discus',g(330,190,1.05,vishnu())+g(110,196,1,tulasi())+g(200,196,1.4,lamp())+g(380,50,1.2,moon()))
pp=[foreword(i,['Twice every lunar month, on the eleventh day after the new moon and the full moon, millions of Hindus fast and pray to Viṣṇu. This day is <b>Ekādaśī</b>, “the eleventh”, and it is the most widely kept vow in the Vaiṣṇava tradition.','Our <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī article</a> covered the greatest of them. This 28-part series covers them all: what Ekādaśī is, how the fast is kept, and then the 26 named Ekādaśīs of the year, each in its own article, with its story.'],[('z','Two fasts every month? That’s a lot.'),('b','It is a rhythm, not a punishment. Many keep only some; the stories say even one, sincerely kept, bears fruit.')]),
 glance([('Name','Ekādaśī, “the eleventh” lunar day (tithi)'),('How often','Twice a month: in the bright half (śukla) and the dark half (kṛṣṇa)'),('Number','24 a year; 26 in a leap year with an extra month'),('Deity','Viṣṇu; Ekādaśī herself is a goddess born from him'),('Practice','Fasting (especially from grains), prayer, night vigil; breaking the fast on Dvādaśī'),('Texts','Ekādaśī māhātmyas in the Padma and Bhaviṣyottara Purāṇas, told by Kṛṣṇa to Yudhiṣṭhira'),('Greatest','Vaikuṇṭha (Mokṣadā), Nirjalā, Devaśayanī, Prabodhinī')],moon_phases()),
 reading('tithi','THE ELEVENTH DAY','What a tithi is',moon_phases(),['<b>The lunar day.</b> The Hindu calendar counts days by the moon. A <b>tithi</b> is the time the moon takes to move 12 degrees ahead of the sun, so there are 30 tithis in a lunar month: 15 in the bright half, waxing to the full moon, and 15 in the dark half, waning to the new moon.','<b>The eleventh.</b> <b>Ekādaśī</b> is the 11th tithi of each half. So there are two each month: <i>śukla</i> (bright) Ekādaśī and <i>kṛṣṇa</i> (dark) Ekādaśī.','<b>Tithis and calendar days.</b> A tithi does not match a calendar day exactly, so almanacs (<a href="/festivals/panchanga/">pañcāṅga</a>) decide on which day it is kept. Sometimes Smārta and Vaiṣṇava calendars differ by a day.','<b>Named days.</b> Each of the 24 Ekādaśīs has its own name and story in the Purāṇas.'],[('z','So Ekādaśī can fall on any weekday?'),('b','Any. It follows the moon, not the week.')],'Ekādaśī: <b>the 11th lunar day, twice a month</b>.'),
 story('mura','THE GODDESS WHO SLEW MURA','The birth of Ekādaśī (Utpannā)',strip('Three panels: the demon Mura; Viṣṇu asleep in a cave; a goddess with a sword springing from him',[EK['utpanna']['strip'][0],EK['utpanna']['strip'][1],EK['utpanna']['strip'][2]],EK['utpanna']['caps']),'Kṛṣṇa told this story to Yudhiṣṭhira.',EK['utpanna']['steps'],[('z','So Ekādaśī is a person, not just a date?'),('b','In the story, a goddess: Viṣṇu’s own power. Keeping her day is honouring her.')],'From Viṣṇu’s body <b>Ekādaśī was born</b>, and slew Mura.'),
 reading('why','WHY ELEVEN, AND WHY FAST','Readings across the tradition',svg(560,160,'Ten sense organs and the mind drawn as eleven small lamps',''.join(g(40+k*48,120,.8,lamp('#1d6fb8' if k<10 else '#e0a800')) for k in range(11))+lab(260,150,'ten senses and the mind: eleven')),['<b>The eleven.</b> A traditional reading counts the five organs of knowledge, the five organs of action and the mind: eleven in all. Ekādaśī is the day to bring all eleven back to God.','<b>Fasting.</b> Fasting quiets the body, so the mind can turn inward. The Purāṇas praise the Ekādaśī fast above other vows.','<b>Viṣṇu’s day.</b> Above all, it is a day for remembering Viṣṇu: chanting his names, reading the Gītā or Bhāgavatam, singing.','<b>Health?</b> Many today speak of health benefits of a fortnightly fast; that is a modern reading, not the tradition’s reason.'],[('z','So the fast is a tool, not the goal?'),('b','Exactly. The goal is remembering the Lord. The fast clears the way.')],'Eleven senses turned to God: <b>the meaning of the day</b>.'),
 reading('year','THE YEAR OF EKĀDAŚĪS','Twenty-four names, two per month',svg(560,180,'A wheel of twelve months with two dots each',''.join(f'<circle cx="{280+80*math.cos(a)}" cy="{90+70*math.sin(a)}" r="16" fill="#dfe9f6" stroke="#111" stroke-width="2"/><circle cx="{280+80*math.cos(a)-5}" cy="{90+70*math.sin(a)}" r="3" fill="#2a2a3a"/><circle cx="{280+80*math.cos(a)+5}" cy="{90+70*math.sin(a)}" r="3" fill="#fff8d0" stroke="#111"/>' for a in [k*math.pi/6 for k in range(12)])+g(280,115,.6,vishnu())),['<b>Every one named.</b> From Kāmadā in spring to Āmalakī before Holī, every Ekādaśī has a name, a story and a promised fruit. The leap month adds two more, Padminī and Paramā.','<b>The great ones.</b> <b>Devaśayanī</b> (Viṣṇu sleeps) and <b>Prabodhinī</b> (he wakes) frame the four months of Cāturmāsya. <b>Nirjalā</b> is the hardest. <b>Vaikuṇṭha</b> (Mokṣadā) is the holiest in the south.','<b>Two ways of naming months.</b> North India ends each month on the full moon; Karnataka and much of the south end it on the new moon. The bright Ekādaśīs fall in the same month either way, but each dark Ekādaśī belongs to the next month in the northern reckoning. This series follows the common northern list and notes the difference.','<b>This series.</b> Each of the 26 has its own article: '+', '.join(L(2+n,EK[k]['name']) for n,k in enumerate(ORDER))+'.'],[('z','So in Mysuru the dark ones are a month “earlier”?'),('b','By name of month, yes. The day itself is the same; only the month label changes.')],'<b>26 named Ekādaśīs</b>, two per month, two more in a leap year.'),
 cards('stories','WHAT THE STORIES SHARE','Patterns in the Ekādaśī tales',svg(560,160,'Icons: a broken chain, a gift of merit, a lamp at night and a fresh start',g(80,130,1,hook())+g(210,130,1.2,lamp())+g(350,130,1,person('#c0392b'))+g(480,120,1,sun(18))),[('🔓','Release','Almost every story ends in release: from a curse, a ghost’s state, illness, poverty or sin.'),('🎁','Merit given away','Again and again the fruit of a fast is given to someone else: a husband, a father, a king, a stranger.'),('🌙','Accidental vows','Several heroes keep the fast without knowing it, through hunger or cold, and are still blessed.'),('🌅','A fresh start','Thieves, hunters, wastrels and proud saints all get a new beginning. No one is beyond it.')],[('z','The stories are quite kind.'),('b','They are. They teach that grace is wider than our failures. That is why people love them.')],'Release, giving, grace, <b>a fresh start</b>.'),
 end(i,['<b>What.</b> The 11th tithi of each lunar half: twice a month.','<b>Who.</b> Viṣṇu, and Ekādaśī, the goddess born from him to slay Mura.','<b>Why.</b> Eleven senses turned to God; the fast clears the way.','<b>How many.</b> 24 named Ekādaśīs, 26 in a leap year.','<b>Stories.</b> Release, merit shared, grace for all.'],'Part 2 is practical: how the fast is kept, the night vigil, why grains are avoided, and how to break the fast on Dvādaśī.','What Ekādaśī is'),
 sources([('Texts:','Ekādaśī māhātmyas of the Padma Purāṇa (Uttara Khaṇḍa) and Bhaviṣyottara Purāṇa, as commonly retold. Wikipedia, “Ekadashi”.'),('Calendar:','Pūrṇimānta and amānta month systems; the pañcāṅga.')],'the eleven-senses reading (one of several); exact order of month names in regional calendars.','Ekādaśī names follow the common pūrṇimānta (northern) list.')]
build(i,'PART 1 OF 28 · THE ELEVENTH DAY · VIṢṆU',COV,'Moon, lamp, tulasī and the Lord','First <b>what a tithi is</b>, then <b>Ekādaśī’s birth</b> from Viṣṇu, why eleven, the <b>year of 26 Ekādaśīs</b>, and what their stories share.','What Ekādaśī is: the eleventh lunar day, the goddess Ekādaśī born from Viṣṇu to slay Mura, why the day is kept, the 24 named Ekādaśīs of the year and the leap-month two, and the themes of their stories. Part 1 of the illustrated Ekādaśī series.',pp)
# ---------------- Part 2
i=1
COV=covart('A plate with fruit and milk, a lamp burning through the night, and a sunrise for breaking the fast',g(110,190,1.2,'<ellipse rx="60" ry="14" fill="#dfe6ee"/>'+''.join(f'<circle cx="{x}" cy="-10" r="10" fill="{c}"/>' for x,c in [(-30,'#f08a24'),(0,'#c0392b'),(30,'#e0a800')]))+g(230,196,1.5,lamp())+g(350,150,1,sun(22))+g(220,50,1.1,moon()))
pp=[foreword(i,['In '+L(0,'Part 1')+' we met Ekādaśī, the eleventh day, and the goddess born from Viṣṇu. Now the practical side: how the day is kept.','There are many levels, from a complete fast to simply avoiding grains, and the tradition is clear that health and circumstance matter. We describe the common shape; your family and teacher come first.'],[('z','Is there one correct way?'),('b','No. There are strict ways and gentle ways. Pick what you can keep sincerely.')]),
 glance([('Daśamī (10th)','Eat simply, once, before sunset; prepare the mind'),('Ekādaśī (11th)','Fast at your level; prayer, Viṣṇu’s names, reading'),('Night','Jāgaraṇa: stay awake singing and listening, if you can'),('Dvādaśī (12th)','Break the fast (pāraṇa) in the morning, within the proper time'),('Avoided','Grains and beans (rice above all), in most traditions'),('Excused','The sick, elderly, pregnant, children, by tradition'),('Date','Follow your pañcāṅga; Smārta and Vaiṣṇava dates sometimes differ')],svg(560,120,'Three days drawn as three boxes: the tenth, eleventh and twelfth',''.join(f'<rect x="{40+k*170}" y="20" width="140" height="80" rx="10" fill="{c}" stroke="#111" stroke-width="2"/>'+lab(110+k*170,66,t,13) for k,(c,t) in enumerate([('#fff3cf','Daśamī: prepare'),('#dfe9f6','Ekādaśī: fast'),('#cfe0b8','Dvādaśī: break')])))),
 cards('levels','LEVELS OF FASTING','From strict to simple',svg(560,150,'Five glasses or plates showing levels: empty, water, fruit and milk, one meal without grain, normal food without grain',''.join(g(60+k*110,120,1,o) for k,o in enumerate(['<rect x="-14" y="-30" width="28" height="30" fill="#fff" stroke="#111" stroke-width="2"/>','<rect x="-14" y="-30" width="28" height="30" fill="#fff" stroke="#111" stroke-width="2"/><rect x="-12" y="-16" width="24" height="14" fill="#8fb8de"/>',pot('#f08a24'),'<ellipse rx="26" ry="8" fill="#e8c06a"/>','<ellipse rx="26" ry="8" fill="#c9e27a"/>']))+''.join(lab(60+k*110,145,t) for k,t in enumerate(['nirjala','water','fruit, milk','one meal','no grains']))),[('💧','Nirjalā','No food and no water, from sunrise to the next sunrise. Traditionally only for Nirjalā Ekādaśī or the very strong.'),('🍎','Phalāhāra','Fruit, milk, nuts: the most common full fast.'),('🍲','Ekabhakta','One meal of non-grain food, often sago, potato, millet-free items as per family custom.'),('🌾','No grains','At the simplest, eat normally but avoid rice, wheat, pulses and beans. Even this is keeping Ekādaśī.')],[('z','Which one should I do?'),('b','The one you can keep cheerfully. A harsh fast kept angrily misses the point.')],'Nirjalā, fruit, one meal, or no grains: <b>choose sincerely</b>.'),
 reading('grains','WHY NO RICE','The grain rule',svg(560,160,'A bowl of rice crossed out, beside fruits and milk',g(170,120,1.5,'<ellipse rx="40" ry="12" fill="#fff"/><path d="M-40 0 q40 30 80 0" fill="#c9783a" stroke="#111" stroke-width="2"/>')+'<path d="M130 70 L210 150 M210 70 L130 150" stroke="#c0392b" stroke-width="6"/>'+g(390,140,1.4,pot('#f08a24'))),['<b>The rule.</b> In nearly all traditions grains (especially rice) and beans are avoided on Ekādaśī, even by those who do not fully fast.','<b>The story.</b> A popular teaching, found in later Vaiṣṇava texts, says that on Ekādaśī sin takes shelter in grains, so eating them takes it in. It is a vivid way of saying: this day, eat lightly and simply.','<b>Rice above all.</b> South Indian households, where rice is the staple, are often strictest about rice.','<b>What is eaten.</b> Fruit, milk, curd, nuts, root vegetables, sago and certain flours, with variations by family.'],[('z','Is the story literal?'),('b','Some take it so; many take it as teaching. Either way, the practice is to eat simply and keep God in mind.')],'Grains, above all rice, <b>are set aside</b>.'),
 reading('vigil','THE NIGHT VIGIL','Jāgaraṇa',svg(560,170,'People seated singing at night before a lamp and an image of Viṣṇu, with a drum and cymbals','<rect width="560" height="170" fill="#2a2a3a"/>'+g(280,160,.9,vishnu())+g(160,160,1.4,lamp())+''.join(g(x,160,.8,person(c,seat=True)) for x,c in [(380,'#c0392b'),(430,'#e0a800'),(480,'#2a9d6f')])),['<b>Staying awake.</b> The stories again and again praise <b>jāgaraṇa</b>, keeping awake through the night of Ekādaśī, singing bhajans, chanting names and listening to stories.','<b>Why.</b> Sleep is the most ordinary thing we do; giving up one night of it for God is a small, real offering. Several Ekādaśī heroes are saved precisely because they stayed awake, even by accident.','<b>Communities.</b> Temples and maṭhas often hold all-night bhajans on the great Ekādaśīs, especially Vaikuṇṭha.','<b>If you can’t.</b> Stay up a little later with a reading or a few names. The tradition values sincerity over endurance.'],[('z','All night, every Ekādaśī?'),('b','Few do that. Most keep the vigil on the great ones. Even an hour counts.')],'Jāgaraṇa: <b>a night given to the Lord</b>.'),
 reading('parana','BREAKING THE FAST','Pāraṇa on Dvādaśī',svg(560,160,'A sunrise and a plate with a tulasī leaf, water and simple food',g(120,100,1,sun(24))+g(330,130,1.4,'<ellipse rx="50" ry="12" fill="#5a8a3a"/>'+''.join(f'<circle cx="{x}" cy="-6" r="7" fill="#fff"/>' for x in (-20,0,20)))+g(470,140,.8,tulasi())),['<b>Pāraṇa.</b> The fast is properly broken on <b>Dvādaśī</b>, the twelfth day, in the morning, within a window set by the almanac. Breaking it too late or skipping pāraṇa is said to spoil the vow.','<b>First things.</b> Many begin with a tulasī leaf, water or a little of the food offered to Viṣṇu, then a simple meal.','<b>Feeding others.</b> Feeding a guest, a brahmin or someone in need before eating is a traditional part of pāraṇa.','<b>Ambarīṣa.</b> The great story of pāraṇa is King Ambarīṣa and the sage Durvāsas, told in our <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī article</a>.'],[('z','Why does the timing matter so much?'),('b','Because the vow has a shape: prepare, keep, complete. Pāraṇa is the completion. Ambarīṣa risked a sage’s curse rather than miss it.')],'Pāraṇa on Dvādaśī: <b>the vow completed</b>.'),
 reading('dates','WHICH DAY? SMĀRTA AND VAIṢṆAVA','Why calendars sometimes differ',svg(560,140,'Two calendar pages side by side showing Ekādaśī on consecutive days',''.join(f'<rect x="{120+k*200}" y="20" width="120" height="100" rx="8" fill="#fff" stroke="#111" stroke-width="2"/><rect x="{120+k*200}" y="20" width="120" height="24" fill="{c}" stroke="#111" stroke-width="2"/>'+lab(180+k*200,37,t,11)+f'<text x="{180+k*200}" y="98" text-anchor="middle" font-family="Georgia,serif" font-size="42" fill="#1d4f8a">{d}</text>' for k,(c,t,d) in enumerate([('#e0a800','Smārta','11'),('#5a8ad0','Vaiṣṇava','12')]))),['<b>The rule of overlap.</b> When Daśamī (the 10th tithi) is still running at dawn of the day Ekādaśī begins, many Vaiṣṇava traditions consider that day “touched” by Daśamī and fast on the next day instead.','<b>So two dates.</b> Almanacs sometimes list a Smārta Ekādaśī and a Vaiṣṇava (or Bhāgavata) Ekādaśī a day apart.','<b>What to do.</b> Follow your family’s and your sampradāya’s calendar: Mādhva, Śrīvaiṣṇava, Smārta and Gauḍīya calendars each have their rules.','<b>Mahā-dvādaśī.</b> Some calendars also mark special Dvādaśīs on which the fast is kept instead. These are details for your almanac.'],[('z','That sounds complicated.'),('b','It is, so let the almanac do it. Your part is the fast and the prayer.')],'Follow <b>your own tradition’s calendar</b>.'),
 reading('care','A WORD OF CARE','Who is excused, and when',svg(560,150,'An elderly person, a pregnant woman and a child, each with a heart symbol',g(140,130,1,person('#7a3fa0'))+g(280,130,1,person('#c0392b'))+g(420,130,1,child())+''.join(f'<path d="M{x} 40 q-10 -12 -20 0 q0 10 20 22 q20 -12 20 -22 q-10 -12 -20 0z" fill="#c0392b"/>' for x in (140,280,420))),['<b>The tradition itself excuses.</b> Children, the elderly, the sick, pregnant and nursing women, and those doing heavy labour are traditionally exempt from strict fasting, or keep a light form.','<b>Medical conditions.</b> Anyone with diabetes, low blood pressure, kidney disease or on regular medication should speak to their doctor before fasting, and should never attempt a waterless fast.','<b>A substitute.</b> Those who cannot fast can avoid grains, chant, read, give food to others or keep the night vigil: all are part of Ekādaśī.','<b>The spirit.</b> The stories reward sincerity, not suffering.'],[('z','So I don’t have to fast to keep Ekādaśī?'),('b','Fasting is the classic form. But remembering Viṣṇu is the heart, and no one is excused from that, or needs to be.')],'Health first; <b>the heart of the day is remembrance</b>.'),
 end(i,['<b>Three days.</b> Prepare on Daśamī, keep Ekādaśī, complete on Dvādaśī.','<b>Levels.</b> Waterless, fruit, one meal, or simply no grains.','<b>Night.</b> Jāgaraṇa: a vigil of names and songs.','<b>Pāraṇa.</b> Break the fast in the right window, feeding others.','<b>Care.</b> The weak and sick are excused; remembrance is for all.'],'From Part 3 each Ekādaśī has its own article, beginning with Caitra’s Pāpamocanī.','Keeping the vow'),
 sources([('Practice:','Wikipedia, “Ekadashi” (fasting levels, grains, jāgaraṇa, pāraṇa, Smārta and Vaiṣṇava dates). The Ambarīṣa story: Bhāgavata Purāṇa 9.4–5.')],'the “sin in grains” teaching (later Vaiṣṇava texts); detailed Daśamī-overlap rules (differ by sampradāya).','Practical guidance is general; follow your teacher, calendar and doctor.')]
build(i,'PART 2 OF 28 · FAST · VIGIL · PĀRAṆA',COV,'The fast, the night and the morning after','The <b>three days</b> of the vow, the <b>levels of fasting</b>, why rice is avoided, the <b>night vigil</b>, <b>pāraṇa</b>, which date to keep, and a word of care.','How to keep Ekādaśī: the three days, levels of fasting, why grains are avoided, the night vigil (jāgaraṇa), breaking the fast on Dvādaśī (pāraṇa), Smārta and Vaiṣṇava dates, and who is excused. Part 2 of the illustrated Ekādaśī series.',pp)

# ---------------- one article per Ekādaśī
MNAMES=[m for _,m,_,_ in MONTHS]
def amanta(k):
    m,_,_=MON[k]
    if m=='Adhika Māsa' or EK[k]['pak']=='bright': return m
    j=MNAMES.index(m); return MNAMES[(j-1)%12]
for n,k in enumerate(ORDER):
    i=2+n; d=EK[k]; x=MORE[k]; mon,season,_=MON[k]
    prev_k=ORDER[n-1] if n>0 else None; next_k=ORDER[n+1] if n+1<len(ORDER) else None
    pair=[o for o in ORDER if MON[o][0]==mon and o!=k][0]
    pl=lambda kk: L(2+ORDER.index(kk),EK[kk]['name']+' Ekādaśī')
    nm=d['name'].split(' (')[0]
    COV=covart(f'A lamp and Viṣṇu for {nm} Ekādaśī, with a scene from its story',g(110,196,1.6,lamp('#2a2a3a' if d['pak']=='dark' else '#fff8d0'))+g(330,190,1.05,vishnu())+g(220,60,1.2,moon() if d['pak']=='bright' else '<circle r="14" fill="#2a2a3a" stroke="#111" stroke-width="2"/>'))
    pp=[foreword(i,[f'This article is about <b>{d["name"]} Ekādaśī</b>, the Ekādaśī of the {d["pak"]} fortnight of <b>{mon}</b>, the season of {season}. Its name means {d["mean"]}.',f'{x["teller"]} Here is its story in full, its characters, what it teaches, what its māhātmya promises, and how it is kept. '+('Before it comes '+pl(prev_k)+'; ' if prev_k else '')+('after it, '+pl(next_k)+'.' if next_k else 'It is the last of the 26.')],[('z',f'What is {nm} Ekādaśī known for?'),('b',d['k'].replace('<b>','').replace('</b>','')+'.')]),
     glance([('Name',f'{d["name"]} Ekādaśī: {d["mean"]}'),('When',f'{mon}, {d["pak"]} fortnight (northern reckoning)'),('In Karnataka’s calendar',f'{amanta(k)}, {d["pak"]} fortnight'),('Told by',x['teller']),('Story',' → '.join(d['caps'])),('Promised fruit',x['fruits']),('Pair',f'With {pl(pair)} in the same month')],svg(560,150,f'A lamp and Viṣṇu for {nm}',g(180,140,1.6,lamp())+g(380,140,1,vishnu()))),
     reading('name',f'THE NAME {nm.upper()}',d['mean'],d['mfig'],[d['mp'][0],f'<b>The fortnight.</b> It falls in the {d["pak"]} fortnight, when the moon is {"waning toward the new moon" if d["pak"]=="dark" else "waxing toward the full moon"}; '+('dark-fortnight Ekādaśīs are often kept with special thought for release and for the departed.' if d['pak']=='dark' else 'bright-fortnight Ekādaśīs often carry the great festivals of Viṣṇu.'),f'<b>The month.</b> {mon} is the season of {season}.',f'<b>Its place in the year.</b> '+('It follows '+pl(prev_k)+' and ' if prev_k else 'It ')+('comes before '+pl(next_k)+'.' if next_k else 'closes the cycle of 26.')],[('z','Is the name important?'),('b','In every Ekādaśī the name is a summary of the story. Remember the name and you remember the lesson.')],f'{nm}: <b>{d["mean"]}</b>.'),
     reading('teller','WHO TELLS THE STORY','The frame of the māhātmya',fig_row('Kṛṣṇa speaking to Yudhiṣṭhira',[(person('#5a8ad0'),1.2),(person('#1d6fb8'),1.2)],['Kṛṣṇa','Yudhiṣṭhira'],gy=160),[f'<b>The teller.</b> {x["teller"]}','<b>Stories within stories.</b> Ekādaśī māhātmyas are nested: Kṛṣṇa answers Yudhiṣṭhira’s question by retelling what a sage once told a king, so each story carries the authority of a chain of tellers.','<b>The sources.</b> These māhātmyas are found mainly in the Padma Purāṇa (Uttara Khaṇḍa) and the Bhaviṣyottara Purāṇa, and are printed together in popular Ekādaśī books. Details differ between editions.','<b>Read at the vow.</b> The story is read or heard on the day, usually after worship; hearing it is itself said to bring merit.'],[('z','Why so many layers of tellers?'),('b','It’s how the Purāṇas work: wisdom passed down hand to hand, like the lamp of the guru-paramparā.')],'A story told <b>from teller to teller</b>.'),
     story('story',f'THE STORY OF {nm.upper()}','The vrata kathā in order',strip(f'Three panels from the story of {nm}',d['strip'],d['caps']),d['lead'],d['steps'],d['talk'],d['k']),
     cards('people','WHO IS WHO','The characters of the story',fig_row('The characters of the story',[(person('#1d6fb8'),1),(sage('#ff8c1a'),1),(person('#c0392b'),1),(vishnu(),.8)],['','','',''],gy=160),x['chars'],[('z','Who is the real hero?'),('b','Usually the one who changes. And behind every story, Viṣṇu’s grace.')],'Four figures, <b>one lesson</b>.'),
     reading('lesson','WHAT IT TEACHES','The meaning of the story',svg(560,150,'A lamp lit from another lamp',g(200,120,1.6,lamp('#2a2a3a'))+'<path d="M240 90 q40 -30 80 0" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="5 4"/>'+g(360,120,1.6,lamp('#fff8d0'))),[d['mp'][1],d['mp'][2],'<b>In one line.</b> '+d['k'].replace('<b>','').replace('</b>','')+'.','<b>The family of stories.</b> Like the other 25, it ends in release and a fresh start; see what the stories share in '+L(0,'Part 1')+'.'],None,'The lesson of '+nm+': <b>'+d['k'].split('<b>')[-1].replace('</b>','').rstrip('.')+'</b>.'),
     reading('fruits','WHAT THE MĀHĀTMYA PROMISES','Phala-śruti',svg(560,140,'A full pot overflowing with flowers',g(280,120,2,pot('#e0a800'))+g(280,70,1.4,lotus())),[f'<b>The promise.</b> {x["fruits"]}','<b>Phala-śruti.</b> Every māhātmya ends with a “hearing of the fruits” (phala-śruti), listing what the vow is said to give. These lists are generous by design: they are meant to encourage.','<b>Read with sense.</b> Teachers say the real fruit of any Ekādaśī is a mind turned to God; the other promises follow from that or are signs of it.','<b>Hearing counts.</b> Most māhātmyas say that even hearing or reading the story with faith brings part of the merit.'],[('z','Is it like a reward list?'),('b','A list of encouragements. The best reward is the change in the person who keeps the vow.')],'The promised fruit, <b>and the real one</b>.'),
     reading('keeping','KEEPING THIS EKĀDAŚĪ','What is special about the day',svg(560,150,'A small altar with a lamp, tulasī and a book',g(180,130,1.4,lamp())+g(300,130,1,tulasi())+g(420,120,1.4,book())),[f'<b>Special to this day.</b> {x["custom"]}','<b>The usual vow.</b> Prepare on Daśamī with a simple meal; on Ekādaśī fast at your level and avoid grains; worship Viṣṇu with tulasī; hear the story; keep a vigil if you can; break the fast on Dvādaśī within the pāraṇa window. Details are in '+L(1,'Part 2: Keeping the Vow')+'.','<b>Which date.</b> Check your pañcāṅga; Smārta and Vaiṣṇava calendars sometimes differ by a day.','<b>Care.</b> The old, sick, pregnant and children are traditionally excused from strict fasting.'],None,f'Keep {nm} <b>with its own special touch</b>.'),
     reading('calendar','WHEN IT FALLS','Two calendars',svg(560,140,'Two calendar pages with the month names',''.join(f'<rect x="{120+j*200}" y="20" width="120" height="100" rx="8" fill="#fff" stroke="#111" stroke-width="2"/>'+lab(180+j*200,60,t,12)+lab(180+j*200,90,mm,13) for j,(t,mm) in enumerate([('Northern',mon),('Karnataka',amanta(k))]))),[f'<b>Northern name.</b> In the full-moon-ending (pūrṇimānta) calendar of the north, {nm} falls in <b>{mon}</b>.',f'<b>Karnataka name.</b> In the new-moon-ending (amānta) calendar used in Karnataka, it falls in <b>{amanta(k)}</b>'+('; the day itself is the same.' if amanta(k)!=mon else ', the same month name.'),'<b>Season.</b> '+f'It comes in the season of {season}.','<b>Your almanac.</b> The exact day is set by the pañcāṅga for your place.'],None,f'{mon} in the north, <b>{amanta(k)} in Karnataka</b>.'),
     cards('related','RELATED READING','Around this Ekādaśī',fig_row('Books and lamps',[(book(),1.4),(lamp(),1.4),(book(),1.4)],['','',''],gy=None),[('🌗','Its pair',f'The other Ekādaśī of {mon}: {pl(pair)}.'),('⬅️','Before',pl(prev_k) if prev_k else 'This is the first in our order.'),('➡️','After',pl(next_k) if next_k else 'The last of the 26.'),('📖','The foundations',L(0,'What Ekādaśī is')+' and '+L(1,'Keeping the Vow')+'.')],None,'Read on <b>through the year</b>.'),
     reading('children','TELLING IT TO CHILDREN','The story in a few lines',svg(560,150,'A grandmother telling a story to two children by a lamp',g(220,140,1.1,person('#7a3fa0',seat=True))+g(320,140,.9,child())+g(370,140,.9,child())+g(470,130,1.2,lamp())),[f'<b>Short version.</b> {d["steps"][0]} {d["steps"][-1]}',f'<b>The question to ask.</b> {d["talk"][0][1]}',f'<b>The answer.</b> {d["talk"][1][1]}','<b>Why tell it.</b> Ekādaśī stories are easy to remember and carry a clear lesson; children who hear them grow up knowing the day.'],None,f'{nm}, <b>told in a minute</b>.'),
     end(i,[f'<b>Name.</b> {nm}: {d["mean"]}.',f'<b>When.</b> {mon}, {d["pak"]} fortnight ({amanta(k)} in Karnataka).',f'<b>Story.</b> {d["caps"][0]} → {d["caps"][2]}.',f'<b>Promise.</b> {x["fruits"]}',f'<b>Lesson.</b> {d["k"].replace("<b>","").replace("</b>","")}.'],('Next: '+PARTS_[i+1][1]+', '+PARTS_[i+1][2]+'.') if i+1<len(PARTS_) else 'That completes the 26 Ekādaśīs.',f'{nm} Ekādaśī'),
     sources([('Story:',f'Ekādaśī māhātmya for {nm} (Padma Purāṇa, Uttara Khaṇḍa; Bhaviṣyottara Purāṇa), as commonly retold; Drik Panchang, “Ekadashi Vrat Katha” index (story identification); Wikipedia, “Ekadashi” (names by month).')],'names of minor characters and places vary between editions; month placement differs between calendars.','Retold in our own words; tellings differ.')]
    build(i,f'PART {i+1} OF 28 · {mon.upper()} · {d["pak"].upper()} FORTNIGHT',COV,f'{nm} Ekādaśī',f'The <b>name</b>, who tells the story, <b>the story</b> in order, its characters, what it <b>teaches</b> and promises, and <b>how it is kept</b>.',f'{nm} Ekādaśī ({mon}, {d["pak"]} fortnight): its name, the vrata kathā from the Purāṇic māhātmya, the characters, its teaching and promised fruit, how it is kept, and its place in the calendar. Part {i+1} of the illustrated Ekādaśī series.',pp)
print('ek2 ok',len(PARTS_))
